// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address rewardToken) public {
        vm.assume(rewardToken != address(0));
        try c.addReward(rewardToken) {
            (uint40 periodFinish, , uint40 lastUpdateTime, ) = c.rewardData(rewardToken);
            assertTrue(periodFinish == lastUpdateTime, "periodFinish should equal lastUpdateTime after success");
        } catch {
            assertTrue(false, "addReward should not revert");
        }
    }
}

